Q: Using std::apply in a class template A: <p>The reason this won't compile is a fundamental rule of C++ templates: You cannot store a parameter pack (Types...) directly as a class member. I also added something which help as well -  the deduction guide.</p>
<pre><code>#include &lt;tuple&gt;
#include &lt;functional&gt;
#include &lt;utility&gt;

class Path {
public:
    virtual ~Path() = default;
    virtual void executeFunction() const = 0;
};

template&lt;class... Types&gt;
class ViewPath : public Path {
public:
    // Constructor taking the function and the arguments
    ViewPath(std::function&lt;void(Types...)&gt; func, Types... args) 
        : function(std::move(func)), function_args(std::make_tuple(std::move(args)...)) {}

    void executeFunction() const override {
        std::apply(function, function_args);
    }

private:
    std::function&lt;void(Types...)&gt; function;
    std::tuple&lt;Types...&gt; function_args;
};

/* --- Deduction Guide --- */
// This tells the compiler: if you see a function-like object and some arguments,
// use the types of the arguments (Args...) to instantiate ViewPath.
template&lt;typename Callable, typename... Args&gt;
ViewPath(Callable, Args...) -&gt; ViewPath&lt;Args...&gt;;

void myFunc(int a, float b) { /* ... */ }

int main() {
    // No &lt;int, float&gt; required
    // The compiler deduces Types... as {int, float}
    ViewPath p(myFunc, 42, 3.14f); 

    p.executeFunction();
    return 0;
}
</code></pre>
